def validate_loan_redirect(url: str) -> str:
    """
    Return the redirect target for a loan request.
    The site's fallback target is '/'.
    """
    parsed = urlparse(url)
    if not parsed.scheme or parsed.netloc != '':
        return '/'
    # Check if the path starts with / and does not contain any other slashes
    if url.startswith('/'):
        parts = url.split('/')
        if len(parts) == 1:
            return '/'
        else:
            return url
    return '/'
